//! How long ago, as a locale says it (D21): "3 hours ago", "3h ago",
//! "vor 3 Stunden", "قبل ٣ ساعات", from CLDR's past relative-time
//! patterns (dateFields.json, generated by gen.zig). The duration picks
//! the unit: the largest one it holds a whole number of, counted down
//! (59 minutes is "59 minutes ago", 60 is "1 hour ago").

const std = @import("std");
const data = @import("cldr_data");
const cldr = @import("cldr.zig");
const number = @import("number.zig");
const plural = @import("plural.zig");

const Writer = std.Io.Writer;
const Locale = cldr.Locale;

/// CLDR's widths, in the order gen.zig writes them.
pub const Style = enum(u8) {
    /// "3 hours ago"
    long,
    /// "3 hr. ago"
    short,
    /// "3h ago"
    narrow,
};

pub const Unit = enum(u8) { second, minute, hour, day, week, month, year };

/// Each unit's length in seconds. A month and a year are the Gregorian
/// calendar's averages (365.2425 days, a twelfth of that), since a
/// duration has no calendar to count them in.
const unit_seconds = [_]u64{ 1, 60, 3600, 86400, 7 * 86400, 2_629_746, 31_556_952 };

const units = unit_seconds.len;
const categories = 6;

comptime {
    std.debug.assert(data.relative_field_count == 3 * units * categories + 3);
}

/// The unit a duration is written in and how many of it: the largest
/// unit of which it holds at least one, the count rounded down.
pub fn unitOf(seconds: u64) struct { unit: Unit, count: u64 } {
    var u: usize = units - 1;
    while (u > 0 and seconds < unit_seconds[u]) u -= 1;
    return .{ .unit = @enumFromInt(u), .count = seconds / unit_seconds[u] };
}

/// Writes a duration in the past as the locale does: "now" below a
/// second, else the count of `unitOf` in the unit's pattern for its
/// plural category, in the locale's digits and grouping.
pub fn formatAgo(l: Locale, w: *Writer, seconds: u64, style: Style) Writer.Error!void {
    const s = @intFromEnum(style);
    if (seconds == 0) return w.writeAll(cldr.poolString(l.relative[3 * units * categories + s]));
    const u = unitOf(seconds);
    const value: f64 = @floatFromInt(u.count);
    const cat = number.category(l, plural.Rules.find(l.tag), .cardinal, value, .{});
    const base = (s * units + @intFromEnum(u.unit)) * categories;
    const i = l.relative[base + @intFromEnum(cat)];
    const p = cldr.poolString(if (i == 0xffff) l.relative[base + categories - 1] else i);
    // Some categories' patterns spell the number out ("قبل ساعة واحدة").
    const at = std.mem.indexOf(u8, p, "{0}") orelse return w.writeAll(p);
    try w.writeAll(p[0..at]);
    try number.format(l, w, value, .{});
    try w.writeAll(p[at + 3 ..]);
}

// Tests ------------------------------------------------------------------------

const testing = std.testing;

fn ago(tag: []const u8, seconds: u64, style: Style) ![]const u8 {
    const S = struct {
        var buf: [256]u8 = undefined;
    };
    var w: Writer = .fixed(&S.buf);
    try formatAgo(Locale.find(tag), &w, seconds, style);
    return w.buffered();
}

test "units: the largest whole one, counted down" {
    const cases = [_]struct { u64, Unit, u64 }{
        .{ 0, .second, 0 },
        .{ 59, .second, 59 },
        .{ 60, .minute, 1 },
        .{ 3599, .minute, 59 },
        .{ 3600, .hour, 1 },
        .{ 86399, .hour, 23 },
        .{ 86400, .day, 1 },
        .{ 7 * 86400 - 1, .day, 6 },
        .{ 7 * 86400, .week, 1 },
        // 30 days is still 4 weeks; a month is 30.44 days.
        .{ 30 * 86400, .week, 4 },
        .{ 31 * 86400, .month, 1 },
        .{ 364 * 86400, .month, 11 },
        .{ 365 * 86400, .month, 11 },
        .{ 366 * 86400, .year, 1 },
        .{ 1000 * 31_556_952, .year, 1000 },
    };
    for (cases) |c| {
        const u = unitOf(c[0]);
        try testing.expectEqual(c[1], u.unit);
        try testing.expectEqual(c[2], u.count);
    }
}

test "how long ago in English, German, Japanese, Arabic (Egypt), and Russian" {
    try testing.expectEqualStrings("now", try ago("en", 0, .long));
    try testing.expectEqualStrings("1 second ago", try ago("en", 1, .long));
    try testing.expectEqualStrings("7 minutes ago", try ago("en", 7 * 60 + 59, .long));
    try testing.expectEqualStrings("1 hour ago", try ago("en", 3600, .long));
    try testing.expectEqualStrings("3 hours ago", try ago("en", 3 * 3600, .long));
    try testing.expectEqualStrings("3 hr. ago", try ago("en", 3 * 3600, .short));
    try testing.expectEqualStrings("3h ago", try ago("en", 3 * 3600, .narrow));
    try testing.expectEqualStrings("7m ago", try ago("en", 7 * 60, .narrow));
    try testing.expectEqualStrings("5d ago", try ago("en", 5 * 86400, .narrow));
    try testing.expectEqualStrings("2w ago", try ago("en", 14 * 86400, .narrow));
    try testing.expectEqualStrings("1 month ago", try ago("en", 40 * 86400, .long));
    try testing.expectEqualStrings("1,234 years ago", try ago("en", 1234 * 31_556_952, .long));
    try testing.expectEqualStrings("vor 3 Stunden", try ago("de", 3 * 3600, .long));
    try testing.expectEqualStrings("vor 1 Stunde", try ago("de", 3600, .long));
    try testing.expectEqualStrings("vor 3 Std.", try ago("de", 3 * 3600, .narrow));
    try testing.expectEqualStrings("vor 5 Tagen", try ago("de", 5 * 86400, .narrow));
    try testing.expectEqualStrings("jetzt", try ago("de", 0, .narrow));
    try testing.expectEqualStrings("3 時間前", try ago("ja", 3 * 3600, .long));
    try testing.expectEqualStrings("3時間前", try ago("ja", 3 * 3600, .narrow));
    // Arabic: the locale's digits, and categories whose patterns have
    // no number.
    try testing.expectEqualStrings("قبل ٣ ساعات", try ago("ar-EG", 3 * 3600, .long));
    try testing.expectEqualStrings("قبل ساعة واحدة", try ago("ar-EG", 3600, .long));
    try testing.expectEqualStrings("قبل ساعتين", try ago("ar-EG", 2 * 3600, .narrow));
    try testing.expectEqualStrings("قبل ١١ ساعة", try ago("ar-EG", 11 * 3600, .long));
    // Russian: one, few, and many.
    try testing.expectEqualStrings("21 час назад", try ago("ru", 21 * 3600, .long));
    try testing.expectEqualStrings("22 часа назад", try ago("ru", 22 * 3600, .long));
    try testing.expectEqualStrings("5 дней назад", try ago("ru", 5 * 86400, .long));
    try testing.expectEqualStrings("-5 дн.", try ago("ru", 5 * 86400, .narrow));
}
